 v:[["Frequenza cardiaca adulto","60-100 battiti/min"],["Frequenza respiratoria adulto","12-20 atti/min"],["Pressione arteriosa ottimale","< 120/80 mmHg; ipertensione ≥ 140/90"],["SpO2","94-98% (88-92% nel BPCO con rischio di ipercapnia)"],["Temperatura","36-37,5 °C (ascellare)"],["NEWS2","0-4 basso; 3 in un singolo parametro o 5-6 medio (valutazione urgente); ≥ 7 alto (risposta di emergenza)"]],
